import json,hashlib,datetime
O=Path(__file__).resolve().parent;C=Path('/tmp/medina-g09-source-cache');now=datetime.datetime.now(datetime.timezone.utc).isoformat();rows=[]
def add(id,url,publisher,path,version,section,passage,population,limits):
 p=Path(path)
 rows.append(dict(id=id,url=url,publisher=publisher,cache_path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),version=version,section=section,passage=passage,passage_type='faithful_paraphrase',population=population,limits=limits,limitations=limits,read_at=now,reader='astra_nephrologie',production_name='Sol-Neurologie-G09',runtime_name='sol_nephrologie',reading_scope='selected_passages_actually_read_or_explicit_same_session_reuse'))
cim='https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686265/master';cp='/tmp/medina-n04-source-cache/CIM.raw'
add('CH-CIM',cim,'OFS, nomenclature suisse',cp,'CIM-10-GM 2024','Classe G09 et note, XML français','G09 vise une séquelle d’état initialement G00–G08 hors catégories astérisque. Le terme comprend les états précisés comme séquelles/effets tardifs, ou présents un an ou plus après le début. Aucun sous-code décimal.','Nomenclature suisse','Un an n’est pas un délai obligatoire si la séquelle est déjà précisée. Le code ne remplace ni diagnostic causal ni recherche de nouvelle activité.')
add('CH-CIM-BOUND',cim,'OFS, nomenclature suisse',cp,'CIM-10-GM 2024','B94.1, B90.0, B00.4†, G05.1* et A84.1','B94.1 nomme les séquelles d’encéphalite virale et B90.0 celles de tuberculose du SNC. B00.4† renvoie à G05.1*. Une suite d’encéphalite virale n’est donc pas automatiquement G09.','Nomenclature suisse','Les cohortes virales éclairent le raisonnement clinique transversal, sans devenir une épidémiologie G09 ou imposer un codage individuel.')
add('CH-PROFILES','https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','CIMS/SMIFK','/workspace/medina-source-cache/C85/profiles2017-official.pdf','2017','EPA 2.2 et SSP 4, 28, 101, 102, 105, 207, 219','Évaluer cognition et mémoire, audition, fatigue, céphalée et crise ; le contexte neurologique urgent et le retentissement fonctionnel relèvent de tâches transversales.','Examen fédéral suisse','Réutilisation du document du même bloc, passages pertinents rouverts ; aucun item fédéral officiel G09 inventé.')
add('CH-MEBEKO','https://www.bag.admin.ch/dam/fr/sd-web/fL9EvX0YPT2d/20260204_Exigences%20MED%202026_f.pdf','OFSP/MEBEKO','/workspace/medina-source-cache/C85/mebeko2026.md','3 mars 2026, examen 2026','Introduction, connaissances et compétences cliniques','L’examen fédéral comporte connaissances cliniques et compétences, avec cadre PROFILES. Les cas MEDINA sont originaux et fictifs.','Examen 2026','Réutilisation explicite de l’introduction lue dans le même bloc ; empreinte du texte fournisseur, pas du PDF original.')
b='https://pmc.ncbi.nlm.nih.gov/articles/PMC11288970/';bp=C/'CH-BERN2024.txt'
add('CH-BERN-METHOD',b,'Schwitter et al., Inselspital/Université de Berne',bp,'17 juillet 2024','Méthodes 2.1–2.3','Cohorte prospective de 50 adultes hospitalisés et 21 témoins, surtout FSME ; purulente bactérienne, encéphalite auto-immune et autres affections chroniques exclues. Examens neurologiques, questionnaires, cognition et actimétrie sélectionnés.','Adultes hospitalisés, cohorte suisse sélectionnée','Ne pas généraliser aux enfants, aux méningites bactériennes, aux AIE ou à tout G09. L’unité de pléiocytose imprimée dans les méthodes n’est pas reprise comme seuil clinique.')
add('CH-BERN-OUTCOME',b,'Schwitter et al., étude suisse',bp,'2024','Résumé, résultats et conclusion','À environ deux ans, des plaintes cognitives, fatigue/somnolence, troubles du sommeil et céphalées persistent chez certains patients, même après des formes initialement légères. Le retentissement social/professionnel doit être recherché.','Cohorte virale adulte, non incidence G09','Fréquences propres à cette étude, symptômes en partie subjectifs et suivi de durée variable ; pas de prédiction individuelle.')
add('CH-BERN-LIMIT',b,'Schwitter et al., étude suisse',bp,'2024','Discussion, limites et conclusion','Petit effectif, contrôles sains imparfaits, recrutement et suivi affectés par la pandémie, consentement source de sélection et risque de rappel. L’amélioration peut continuer sans disparition de toute plainte.','Adultes consentants hospitalisés','Aucune absence de corrélation statistique n’est transformée en preuve universelle que la gravité ne compte jamais.')
of='https://www.bag.admin.ch/dam/fr/sd-web/GaSnHcNnmEXI/zeckenenzephalitis-empfehlung-impfung.pdf'
add('CH-OFSP-CLIN',of,'OFSP et CFV',C/'CH-OFSP-0.txt','8 juillet 2024','Section 2.4, séquelles','Des troubles durables de cognition, fatigue, comportement, attention et fonctions motrices peuvent suivre une atteinte neurologique FSME, y compris chez l’enfant avec retentissement scolaire.','FSME, populations spécifiques','Texte complet fournisseur effectivement consulté par passages ; PDF direct 503, donc empreinte de ce texte et non du PDF. Pas d’incidence G09 déduite.')
add('CH-OFSP-PREV','https://www.bag.admin.ch/fr/meningo-encephalite-a-tiques-fsme','OFSP',C/'CH-OFSP-1.txt','Page en vigueur consultée le 2 novembre 2026','Prévention et vaccination','Vaccination généralement dès trois ans en cas d’exposition aux tiques en zone à risque ; Suisse sauf Tessin dans cette page. Rappel tous les dix ans si risque persistant, schéma dépendant du produit.','Prévention FSME en Suisse','La vaccination prévient une infection ; elle ne répare pas une séquelle. Plan 2026 complet non lu, tentative Infovac 403 et fournisseur sans extraction : ne pas revendiquer sa lecture.')
add('CH-OFSP-IMMUNITY',of,'OFSP et CFV',C/'CH-OFSP-0.txt','Juillet 2024','Section 2.5, immunité après infection','Après infection naturelle VET, IgG persistantes à vie et protection probablement durable ; distinguer infection prouvée, simple exposition et prévention des personnes susceptibles.','Après FSME documentée','Ne pas promettre une vaccination réparatrice ou une revaccination systématique d’une personne avec infection naturelle documentée ; avis individuel.')
add('FI-KEPPRA','https://amiko.oddb.org/fr/fi?gtin=7680552970049','FI suisse UCB-Pharma, Keppra oral',C/'FI-KEPPRA-ORAL.html','Avril 2023','Indications, posologie orale/rénale, précautions, interactions, reproduction et mécanisme','Crises focales : monothérapie dès 16 ans, association dès un mois chez nourrisson né à terme. Adulte et adolescent >40 kg : 500 mg deux fois/jour, départ 250 possible puis 500 après deux semaines, max 1500 deux fois/jour, paliers 250/500 par prise toutes 2–4 semaines. Solution 100 mg/mL, barre du comprimé non destinée à doses égales. Enfant 1–<6 mois 7→21 mg/kg par prise deux fois/jour ; à partir de six mois et <40 kg 10→30. Tables rénales avec populations propres, adaptation hépatique sévère et surveillance. Liaison SV2A contributive, mécanisme incomplet.','Épilepsie selon indication et âge, pas prophylaxie universelle G09','Poids de transition des tableaux 40/50 kg à vérifier ; doses de base et tables rénales non interchangeables. Grossesse si nécessaire à dose efficace minimale avec spécialiste ; allaitement déconseillé et discussion bénéfice/risque si nécessaire. Arrêt progressif, effets comportementaux/somnolence et hypersensibilité à surveiller.')
add('FI-LIORESAL','https://amiko.oddb.org/fr/fi?gtin=7680360830184','FI suisse Novartis, Liorésal oral',C/'FI-LIORESAL-ORAL.html','Janvier 2025','Indications, posologie, organes, précautions, interactions et reproduction','Indication notamment spasticité médullaire infectieuse, pas toute séquelle cérébrale. Adulte 5 mg trois fois/jour au début, augmentation de 5 mg par prise tous trois jours, moyenne 30–80 mg/j, 100–120 uniquement certains cas hospitalisés. Sevrage progressif après usage prolongé ; toxicité rénale/encéphalopathie, sédation et perte de tonus fonctionnel possibles. GABAB médullaire.','Spasticité et indication établies ; enfant dès douze mois avec schéma pondéral spécifique','Ne pas confondre comprimés 10 mg sécables et 25 mg non divisibles en doses égales, ni oral et intrathécal. Grossesse sauf nécessité absolue, pas administration pendant allaitement. Insuffisance rénale et association sédative exigent prudence ; pas d’augmentation devant simple faiblesse.')
add('FI-FSME-CC','https://amiko.oddb.org/fr/fi?gtin=7680004500039','FI suisse Pfizer, FSME-Immun CC',C/'FI-FSME-CC.html','Juillet 2025','Indication, doses, rappels, précautions, interactions et grossesse','Dès seize ans, 0,5 mL IM ; deuxième dose 1–3 mois après première ou dès quatorze jours en schéma rapide, troisième 5–12 mois après deuxième. FI : premier rappel trois ans, puis cinq ans 16–49 ans, trois ans à partir de cinquante ; renvoi explicite aux recommandations officielles nationales.','Prévention, adolescent/adulte selon âge','OFSP actuel dix ans attribué séparément, pas moyenne inventée. Hypersensibilité sévère notamment œuf/poulet, infection fébrile aiguë et immunodéficience à vérifier. Grossesse protection urgente après bénéfice/risque, passage lait inconnu. Aucune indication de réparation d’une séquelle.')
add('FI-FSME-JUNIOR','https://amiko.oddb.org/fr/fi?gtin=7680006830035','FI suisse Pfizer, FSME-Immun Junior',C/'FI-FSME-JUNIOR.html','Juillet 2025','Indication, doses, rappels et précautions','De un an révolu à moins de seize ans, 0,25 mL IM ; délais de primovaccination comparables à CC, formulation adulte dès seize ans. FI : premier rappel trois ans puis cinq ans ; renvoi au calendrier national et prise en compte immunosuppression.','Enfant et adolescent, prévention FSME','Autorisation dès un an distincte de recommandation générale OFSP dès trois ans. Ni double dose Junior ni demi-dose CC inventée ; dose/produit à vérifier. Pas de délai national reconstruit à partir de la seule FI.')
add('CH-EPI','https://www.epi.ch/wp-content/uploads/2026/01/Fahreignung-mit-Epilepsie-Flyer-F.pdf','Ligue Suisse contre l’Épilepsie',C/'CH-EPILEPSY-DRIVING2026.txt','Information novembre 2019, malgré chemin web 2026','Introduction, contexte et actualisation','Crise inaugurale, traitement préventif et diagnostic d’épilepsie doivent être distingués ; évaluation neurologique et circonstances individuelles déterminent l’aptitude.','Source institutionnelle suisse datée','Ne pas présenter les délais imprimés en 2019 comme règles actualisées 2026 ; aucun délai universel de reprise de conduite utilisé dans ce cours.')
n='https://www.nice.org.uk/guidance/ng240/chapter/recommendations';np=C/'EU-NICE2024.txt'
add('EU-NICE-COMPLICATIONS',n,'NICE, NG240',np,'19 mars 2024','Sections 1.12.1–1.12.13','Identifier complications et besoins avant sortie, audition dans quatre semaines après aptitude au test et de préférence avant sortie ; surdité sévère/profonde évaluation urgente d’implant. Révision des antiépileptiques à trois mois, pas arrêt automatique.','Après méningite bactérienne ou maladie méningococcique','Calendrier non universel pour toute encéphalite, myélite ou G09 ; quatre semaines commencent à l’aptitude au test, pas automatiquement à la sortie.')
add('EU-NICE-FOLLOW',n,'NICE, NG240',np,'2024','Sections 1.13.1–1.13.11','Contrôle médical/pédiatrique à 4–6 semaines après sortie ; suivi neurodéveloppemental au moins deux ans chez enfant, vigilance aux transitions scolaires, retour progressif éducation/emploi et adaptations selon besoin.','Population du guide NG240','Âges et horloges distincts ; revue un an après sortie pour nourrisson de moins de douze mois ne supprime pas les autres contrôles. Pas droit suisse automatique.')
add('EU-HSV-AIE','https://pmc.ncbi.nlm.nih.gov/articles/PMC6128696/','Armangue et al., 19 centres espagnols',C/'EU-HSV-AIE2018.txt','2018','Résumé : méthodes, résultats et interprétation','Dans la cohorte prospective de 51 patients HSE, 14 développent une AIE ; anticorps présents aussi chez certains sans AIE. Une nouvelle aggravation comportementale, motrice ou cognitive après HSV exige une nouvelle évaluation.','Cohorte prospective sélectionnée et groupe rétrospectif distincts','Pas de fréquence générale G09 ni diagnostic sur anticorps isolé ; décès précoces et recrutement tardif exclus. HSV cause une question de codage distincte, pas G09 automatique.')
p='https://www.has-sante.fr/upload/docs/application/pdf/2022-01/pnds_nmdar.pdf';pp=C/'EU-PNDS-NMDAR2021.txt'
add('EU-PNDS-REHAB',p,'Centre de référence français, BRAIN-TEAM, PNDS hébergé HAS',pp,'Décembre 2021','Sections 2.1–2.2 et 5.6','Anti-NMDAr : altération synaptique et internalisation de récepteurs documentées notamment expérimentalement ; récupération parfois lente. Rééducation pluridisciplinaire adaptée aux déficits, compétences préservées, fatigue, comportement et projet de vie.','Encéphalite anti-NMDAr, pas toute G09','PNDS de centre expert hébergé HAS, pas présenté comme validation HAS indépendante. Données expérimentales non transformées en prédiction clinique de réversibilité totale ; pas schéma immunothérapeutique universel.')
add('EU-PNDS-FOLLOW',p,'Centre de référence français, PNDS',pp,'2021','Sections 6.1–6.3','Suivi recherche comorbidités, retentissement quotidien, rechute et cognition ; coordination neurologue, rééducateur, neuropsychologue, orthophoniste et ergothérapeute. Enjeux familiaux, scolaires et professionnels persistent.','Après anti-NMDAr, parcours individualisé','Délais et proportions historiques propres au PNDS, sans transfert à toute infection ou aux droits français en Suisse. Le diagnostic de nouvelle activité précède l’étiquette séquelle.')
for id,url,file,section,passage,lim in [
('EU-CEN-PYRAMIDAL','https://www.cen-neurologie.fr/premier-cycle/semiologie-analytique/syndrome-pyramidal','EU-CEN-PYRAMIDAL.txt','Définition, symptômes et signes I–II','Atteinte corticospinale : faiblesse et spasticité peuvent être décalées après lésion aiguë. Bras tendus, Mingazzini, tonus dépendant de l’étirement, réflexes et réponse plantaire localisent sans nommer la cause.','Une hypotonie aiguë n’exclut pas une atteinte centrale ; signe isolé ou photo ne prouve pas une inflammation active.'),
('EU-CEN-CEREBELLAR','https://www.cen-neurologie.fr/premier-cycle/semiologie-analytique/syndrome-cerebelleux','EU-CEN-CEREBELLAR.txt','Symptômes, signes, examens et différentiels I–IV','Ataxie, polygone élargi, hypermétrie doigt-nez/talon-genou, dysarthrie et hypotonie orientent vers cervelet ou ses voies. Différentiels proprioceptif, vestibulaire et frontal.','Aucun test électrophysiologique unique ne confirme ce syndrome ; imagerie cherche lésion et cause, examen sécurisé selon capacités.'),
('EU-CEN-COGNITION','https://www.cen-neurologie.fr/premier-cycle/semiologie-analytique/semiologie-des-fonctions-cognitives','EU-CEN-COGNITION.txt','Définitions, langage, fonctions instrumentales, attention/exécutif et mémoire','Langage, gestes, mémoire, attention et fonctions exécutives sont distincts. Aphasie n’est pas dysarthrie ; apraxie ne se réduit pas à une faiblesse élémentaire.','Ne pas réduire tout échec de test à mémoire déficiente ; audition, langue, fatigue et profil des fonctions doivent être pris en compte sans seuil cognitif universel.')]:
 add(id,url,'Collège des enseignants de neurologie',C/file,'Page non datée, consultée en 2026',section,passage,'Sémiologie neurologique',lim)
for id,url,file,section,passage,lim in [
('NORMAL-TISSUE','https://openstax.org/books/anatomy-and-physiology-2e/pages/12-2-nervous-tissue','NORMAL-TISSUE.txt','Neurones, glie du SNC et myéline','Neurones : soma, dendrites, axone et synapses. Oligodendrocytes myélinisent les axones du SNC ; astrocytes, microglie et épendyme ont des fonctions différentes.','Faits normaux paraphrasés ; aucune image actuelle NC importée, aucune microphotographie interprétée comme dosage de myéline ou d’anticorps.'),
('NORMAL-CSF','https://openstax.org/books/anatomy-and-physiology-2e/pages/13-3-circulation-and-the-central-nervous-system','NORMAL-CSF.txt','Méninges et système ventriculaire','Dure-mère, arachnoïde, espace sous-arachnoïdien et pie-mère sont distincts. LCR produit au niveau des plexus, circulation ventriculaire puis sous-arachnoïdienne et résorption dans le sang.','Schéma classique normal ; pas de mesure de pression ni prescription de ponction lombaire sur une image. Aucun débit ou seuil universel inventé.'),
('NORMAL-ACTION','https://openstax.org/books/anatomy-and-physiology-2e/pages/12-4-the-action-potential','NORMAL-ACTION.txt','Potentiel de membrane, paragraphes sur gradients Na/K et pompe','Gradients ioniques, perméabilité sélective et pompe Na/K participent au potentiel de membrane. La valeur de repos est un exemple variable selon les cellules.','Seuls ces paragraphes sont retenus ; légendes mécanosensibles sur Ca non reprises, pas d’équivalence entre potentiel cellulaire et EEG clinique.'),
('NORMAL-HEARING','https://openstax.org/books/anatomy-and-physiology-2e/pages/14-1-sensory-perception','NORMAL-HEARING.txt','Audition : conduction et cochlée','Son transmis vers tympan, osselets puis liquides cochléaires ; membrane basilaire et cellules ciliées participent à la transduction, information conduite vers le tronc cérébral par voies auditives.','Structures normales paraphrasées, pas d’image actuelle importée. Le schéma Gray ne montre ni perte auditive, ni ossification, ni activité infectieuse individuelle.')]:
 add(id,url,'OpenStax, Anatomy and Physiology 2e',C/file,'2e, page consultée en 2026',section,passage,'Science normale, sans recommandation thérapeutique américaine',lim)
add('EU-HISTO','https://www.histologistes.org/CHEC/images/pedago/resumes/Cortex_Cerebelleux.pdf','Pr Philippe Vago, faculté de médecine Clermont-Ferrand',C/'EU-HISTOLOGY-CEREBELLUM.txt','Document pédagogique non daté','Architecture du cortex, Purkinje et histophysiologie','Trois couches : moléculaire externe, Purkinje, granulaire interne. Les cellules de Purkinje sont une efférence inhibitrice du cortex cérébelleux ; organisation mise en relation avec coordination et posture.','Tissu nerveux normal','Texte court effectivement lu ; aucune figure de ce PDF importée. La photographie humaine Nephron n’a pas de contexte clinique documenté et ne prouve pas une lésion G09.')
